#define FOR(I,A,B) for(int I=(A);I<=(B);I++)
#define REP(I,N) for(int I=0;I<(N);I++)
#define ALL(X) (X).begin(),(X).end()
#define VAR(A,B) __typeof(B) A=B
#define FORE(I,X) for(VAR(I,(X).begin());I!=(X).end();I++)
#define F first
#define S second
