char tab[134];
string imejl;

int main(){
	scanf("%s",tab);
	imejl=tab;
	for(int i=1;i<imejl.size()-1;i++){
		if (imejl[i]=='a' && imejl[i+1]=='t'){
			imejl[i]='@';
			break;
		}
	}
	for(int i=1;i<imejl.size()-3;i++){
		if (imejl[i]=='d' && imejl[i+1]=='o' && imejl[i+2]=='t'){
			imejl[i]='.';
		}
	}
	REP(i,imejl.size()){
		if (imejl[i]=='@'){
		       	printf("@");
			i++;
			continue;
		}
		if (imejl[i]=='.'){
			printf(".");
			i+=2;
			continue;
		}
		printf("%c",imejl[i]);
	}
	printf("\n");
}

